def pair_sum(a, t):
    i, j = 0, len(a) - 1
    while i < j:
        s = a[i] + a[j]
        if s == t: return (i, j)
        if s < t: i += 1
        else: j -= 1
    return None
O(n) time, O(1) space.

def two_sum(a, t):
    seen = {}
    for i, x in enumerate(a):
        if t - x in seen:
            return [seen[t - x], i]
        seen[x] = i
O(n) instead of O(n²).

from collections import Counter
def is_anagram(a, b):
    return Counter(a) == Counter(b)
For lowercase-only input, an int[26] count array is faster.

def balanced(s):
    st, pair = [], {')': '(', ']': '[', '}': '{'}
    for c in s:
        if c in '([{': st.append(c)
        elif not st or st.pop() != pair[c]:
            return False
    return not st

def fib(n):
    if n < 2: return n
    return fib(n-1) + fib(n-2)
Correct but O(2ⁿ): fib(3) is recomputed many times. Memoisation brings it to O(n).

def subsets(a):
    res = []
    def go(i, cur):
        if i == len(a):
            res.append(cur[:]); return
        cur.append(a[i]); go(i + 1, cur)
        cur.pop();        go(i + 1, cur)
    go(0, [])
    return res

